    def getRaw(self, startTime:int=None, stopTime:int=None, idx:int=0, limit:int=1000_000): # TimeSeries
        """Grabs raw data of this time series. Returns something like ``[[1737213223.4139452, (3, 4, 5)], ...]`` """ # TimeSeries
